CREATE TABLE IF NOT EXISTS organizations (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memberships (organization_id TEXT NOT NULL, user_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','admin','member')), created_at TEXT NOT NULL, PRIMARY KEY (organization_id,user_id), FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, name TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS evaluation_runs (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, project_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, status TEXT NOT NULL, provider TEXT NOT NULL, sample_count INTEGER NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY (organization_id) REFERENCES organizations(id), FOREIGN KEY (project_id) REFERENCES projects(id), UNIQUE (organization_id,idempotency_key));
CREATE TABLE IF NOT EXISTS evaluation_results (run_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, result_json TEXT NOT NULL, evidence_metadata_json TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY (run_id) REFERENCES evaluation_runs(id));
CREATE TABLE IF NOT EXISTS usage_events (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, run_id TEXT NOT NULL, units INTEGER NOT NULL, provider_cost_estimate_usd REAL NOT NULL, idempotency_key TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY (organization_id) REFERENCES organizations(id), UNIQUE (organization_id,idempotency_key));
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, user_id TEXT NOT NULL, action TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY (organization_id) REFERENCES organizations(id));
